create or replace function public.claim_daily_streak(p_user_id uuid,p_claimed_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_claim_date date:=timezone('utc',p_claimed_at)::date; v_existing public.daily_streak_claims%rowtype; v_last public.daily_streak_claims%rowtype; v_profile public.profiles%rowtype; v_streak integer:=1; v_reward numeric:=0; v_free_rounds integer:=0; v_reward_kind text:='bonus'; v_wager_required numeric:=0; v_ref text; v_wallet jsonb; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; perform pg_advisory_xact_lock(hashtextextended('daily_streak:'||p_user_id::text||':'||v_claim_date::text,0)); select * into v_existing from public.daily_streak_claims where user_id=p_user_id and claim_date=v_claim_date limit 1; if found then return jsonb_build_object('ok',true,'idempotent',true,'already_claimed',true,'awarded',v_existing.reward_amount,'free_rounds',v_existing.free_rounds_awarded,'reward_kind',v_existing.reward_kind,'streak',v_existing.streak_count,'wagering_required',v_existing.wagering_required,'wagering_progress',v_existing.wagering_progress,'claimed_at',v_existing.claimed_at); end if; select * into v_profile from public.profiles where id=p_user_id for update; if not found then raise exception 'PROFILE_NOT_FOUND'; end if; if coalesce(v_profile.wager_required,0)>coalesce(v_profile.wager_progress,0) then return jsonb_build_object('ok',false,'error','STREAK_WAGERING_ACTIVE','required',v_profile.wager_required,'progress',v_profile.wager_progress); end if; if exists(select 1 from public.promo_claims where user_id=p_user_id and status in ('active','applied')) then return jsonb_build_object('ok',false,'error','PROMO_ACTIVE'); end if; select * into v_last from public.daily_streak_claims where user_id=p_user_id and claim_date<v_claim_date order by claim_date desc limit 1 for update; if found and v_last.claim_date=v_claim_date-1 then v_streak:=(v_last.streak_count%7)+1; else v_streak:=1; end if; case v_streak when 1 then v_reward:=5; when 2 then v_reward:=10; when 3 then v_reward:=15; when 4 then v_reward:=25; when 5 then v_reward:=50; when 6 then v_reward:=100; when 7 then v_reward:=0; v_free_rounds:=10; v_reward_kind:='free_rounds'; else raise exception 'INVALID_STREAK_DAY'; end case; v_wager_required:=round(v_reward*10,2); v_ref:='daily_streak:'||p_user_id::text||':'||v_claim_date::text; if v_reward>0 then v_wallet:=public.wallet_apply_delta(p_user_id=>p_user_id,p_delta_balance=>0,p_delta_bonus=>v_reward,p_delta_locked=>0,p_reason=>'daily_streak_claim',p_ref_id=>v_ref,p_method=>'manual',p_metadata=>jsonb_build_object('day',v_streak,'reward',v_reward,'claim_date',v_claim_date,'wagering_multiplier',10,'wagering_required',v_wager_required)); if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'STREAK_WALLET_APPLY_FAILED'; end if; update public.profiles set wager_required=v_wager_required,wager_progress=0,updated_at=now() where id=p_user_id; end if; if v_free_rounds>0 then insert into public.free_round_entitlements(user_id,game,remaining,source,expires_at,metadata,ref_id) values(p_user_id,'crash',v_free_rounds,'daily_streak',p_claimed_at+interval '7 days',jsonb_build_object('day',v_streak,'claim_date',v_claim_date),v_ref||':free_rounds') on conflict (ref_id) where ref_id is not null do nothing; end if; insert into public.daily_streak_claims(user_id,claim_date,streak_count,reward_amount,claimed_at,wallet_ref_id,free_rounds_awarded,wagering_required,wagering_progress,reward_kind) values(p_user_id,v_claim_date,v_streak,v_reward,p_claimed_at,v_ref,v_free_rounds,v_wager_required,0,v_reward_kind); return jsonb_build_object('ok',true,'idempotent',coalesce((v_wallet->>'idempotent')::boolean,false),'already_claimed',false,'awarded',v_reward,'free_rounds',v_free_rounds,'reward_kind',v_reward_kind,'streak',v_streak,'wagering_required',v_wager_required,'wagering_progress',0,'claimed_at',p_claimed_at,'wallet',v_wallet); end; $$;
create or replace function public.get_daily_streak_status(p_user_id uuid,p_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_date date:=timezone('utc',p_at)::date; v_today public.daily_streak_claims%rowtype; v_last public.daily_streak_claims%rowtype; v_profile public.profiles%rowtype; v_next integer:=1; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; select * into v_today from public.daily_streak_claims where user_id=p_user_id and claim_date=v_date limit 1; select * into v_last from public.daily_streak_claims where user_id=p_user_id and claim_date<=v_date order by claim_date desc limit 1; select * into v_profile from public.profiles where id=p_user_id; if found and v_last.claim_date=v_date-1 then v_next:=(v_last.streak_count%7)+1; elsif found and v_last.claim_date=v_date then v_next:=v_last.streak_count; else v_next:=1; end if; return jsonb_build_object('ok',true,'claimed_today',(v_today.id is not null),'current_streak',coalesce(v_last.streak_count,0),'next_day',v_next,'last_claim_date',v_last.claim_date,'wagering_required',coalesce(v_profile.wager_required,0),'wagering_progress',coalesce(v_profile.wager_progress,0),'can_claim',(v_today.id is null and coalesce(v_profile.wager_required,0)<=coalesce(v_profile.wager_progress,0) and not exists(select 1 from public.promo_claims where user_id=p_user_id and status in ('active','applied')))); end; $$;
revoke all on function public.claim_daily_streak(uuid,timestamptz) from public,anon,authenticated;
revoke all on function public.get_daily_streak_status(uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.claim_daily_streak(uuid,timestamptz) to service_role;
grant execute on function public.get_daily_streak_status(uuid,timestamptz) to service_role;
